const updateCategory = `-- name: UpdateCategory :one
UPDATE categories SET
    name           = COALESCE($1, name),
    urgency        = COALESCE($2, urgency),
    business_lines = COALESCE($3::text[], business_lines),
    sort_order     = COALESCE($4::int, sort_order),
    active         = COALESCE($5::boolean, active),
    updated_at     = $6
WHERE id = $7 AND deleted_at IS NULL
RETURNING id, organization_id, kind, name, urgency, business_lines, sort_order, active, created_at, updated_at, deleted_at
`

type UpdateCategoryParams struct {
	Name          pgtype.Text
	Urgency       NullUrgency
	BusinessLines []string
	SortOrder     pgtype.Int4
	Active        pgtype.Bool
	Now           pgtype.Timestamptz
	ID            int64
}

// A NULL narg leaves the column as it is. urgency is never cleared here: it is required for an
// instruction and absent for a report, and the usecase has checked which this is.
func (q *Queries) UpdateCategory(ctx context.Context, arg UpdateCategoryParams) (Category, error) {
	row := q.db.QueryRow(ctx, updateCategory,
		arg.Name,
		arg.Urgency,
		arg.BusinessLines,
		arg.SortOrder,
		arg.Active,
		arg.Now,
		arg.ID,
	)
	var i Category
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.Kind,
		&i.Name,
		&i.Urgency,
		&i.BusinessLines,
		&i.SortOrder,
		&i.Active,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

